import {
  Body,
  BadRequestException,
  Controller,
  Get,
  Logger,
  Param,
  Post,
  Put,
  Query,
  Req,
  ServiceUnavailableException,
  UseGuards,
  Optional,
} from '@nestjs/common';
import { Request } from 'express';
import { CurrentUser } from '../auth/decorators/current-user.decorator';
import { AuthService } from '../auth/auth.service';
import { OriginGuard } from '../auth/guards/origin.guard';
import { SessionAuthGuard } from '../auth/guards/session-auth.guard';
import { User } from '../users/entities/user.entity';
import { KaraokeSessionService } from './karaoke-session.service';
import { RemoteAuthorizationService } from './remote-authorization.service';
import { KaraokeScoreHistoryService } from './karaoke-score-history.service';

@Controller('karaoke-sessions')
@UseGuards(SessionAuthGuard)
export class KaraokeSessionController {
  private readonly logger = new Logger(KaraokeSessionController.name);

  constructor(
    private readonly sessions: KaraokeSessionService,
    private readonly auth: AuthService,
    private readonly scoreHistory: KaraokeScoreHistoryService,
    @Optional()
    private readonly remoteAuthorization?: RemoteAuthorizationService,
  ) {}

  @Post()
  @UseGuards(OriginGuard)
  create(
    @CurrentUser() user: User,
    @Body() body: { alias?: unknown; clientId?: unknown },
  ) {
    return this.sessions.create(user.id, body?.alias, body?.clientId);
  }

  @Get('active')
  listActive(@CurrentUser() user: User) {
    return this.sessions.listActive(user.id);
  }

  @Get('history')
  listHistory(@CurrentUser() user: User) {
    return this.scoreHistory.listSessionHistory(user.id);
  }

  @Post('claim-guest')
  @UseGuards(OriginGuard)
  async claimGuest(
    @CurrentUser() user: User,
    @Body() body: {
      sessionId?: unknown;
      hostToken?: unknown;
      clientId?: unknown;
      queue?: unknown;
      performers?: unknown;
      alias?: unknown;
      replaceSessionId?: unknown;
    },
  ) {
    const result = await this.sessions.claimGuest(
      user.id,
      body?.sessionId,
      body?.hostToken,
      body?.clientId,
      body?.queue,
      body?.performers,
      body?.alias,
      body?.replaceSessionId,
    );
    if (result.replacedSessionId) {
      await this.remoteAuthorization?.invalidateSession(result.replacedSessionId);
    }
    return result;
  }

  /**
   * A browser on Vercel cannot rely on the Render session cookie during a
   * Socket.IO handshake. Issue a short-lived ticket only after the final,
   * active karaoke session has been verified for the authenticated owner.
   */
  @Get(':sessionId/socket-ticket')
  async socketTicket(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Query('clientId') clientId: string | undefined,
    @Req() request: Request,
  ) {
    const session = await this.remoteAuthorization?.findActiveSession(
      user.id,
      sessionId,
      clientId,
    );
    if (!session) {
      throw new ServiceUnavailableException(
        'Remote authorization is not configured.',
      );
    }
    const ticket = await this.auth.issueSocketTicket(
      this.readCookie(request, this.auth.cookieName),
      session.id,
    );
    this.logger.log(
      `Socket ticket issued for karaoke session ${this.redactSessionId(session.id)}; expires ${ticket.expiresAt.toISOString()}`,
    );
    return ticket;
  }

  @Get(':sessionId/queue')
  queue(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Query('clientId') clientId: string | undefined,
  ) {
    return this.sessions.getQueue(user.id, sessionId, clientId);
  }

  @Get(':sessionId/performers')
  performers(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Query('clientId') clientId: string | undefined,
  ) {
    return this.sessions.getPerformers(user.id, sessionId, clientId);
  }

  @Post(':sessionId/performances')
  @UseGuards(OriginGuard)
  createPerformance(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Body() body: Record<string, unknown>,
  ) {
    return this.scoreHistory.create(user.id, sessionId, body);
  }

  @Get(':sessionId/performances')
  listPerformances(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Query('clientId') clientId: string | undefined,
  ) {
    return this.scoreHistory.list(user.id, sessionId, clientId);
  }

  @Get(':sessionId/leaderboard')
  leaderboard(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Query('clientId') clientId: string | undefined,
  ) {
    return this.scoreHistory.leaderboard(user.id, sessionId, clientId);
  }

  @Get(':sessionId/history')
  historyDetail(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
  ) {
    return this.scoreHistory.getSessionHistoryDetail(user.id, sessionId);
  }

  @Get(':sessionId')
  get(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Query('clientId') clientId: string | undefined,
  ) {
    return this.sessions.get(user.id, sessionId, clientId);
  }

  @Put(':sessionId/queue')
  @UseGuards(OriginGuard)
  replaceQueue(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Body() body: { items?: unknown; clientId?: unknown },
  ) {
    return this.sessions.replaceQueue(
      user.id,
      sessionId,
      body?.items,
      body?.clientId,
    );
  }

  @Put(':sessionId/performers')
  @UseGuards(OriginGuard)
  replacePerformers(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Body() body: { performers?: unknown; clientId?: unknown },
  ) {
    return this.sessions.replacePerformers(
      user.id,
      sessionId,
      body?.performers,
      body?.clientId,
    );
  }

  @Post(':sessionId/transfer')
  @UseGuards(OriginGuard)
  transfer(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Body() body: { includePerformers?: unknown; clientId?: unknown },
  ) {
    const includePerformersOption = body?.includePerformers;
    if (
      includePerformersOption !== undefined &&
      typeof includePerformersOption !== 'boolean'
    ) {
      throw new BadRequestException('includePerformers must be a boolean.');
    }
    const includePerformers =
      includePerformersOption === undefined
        ? true
        : Boolean(includePerformersOption);
    return this.sessions
      .transfer(user.id, sessionId, includePerformers, body?.clientId)
      .then(async (result) => {
        await this.remoteAuthorization?.invalidateSession(sessionId);
        return result;
      });
  }

  @Post(':sessionId/heartbeat')
  @UseGuards(OriginGuard)
  async heartbeat(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Body() body: { clientId?: unknown; takeOver?: unknown },
  ) {
    const takeOverOption = body?.takeOver;
    if (takeOverOption !== undefined && typeof takeOverOption !== 'boolean') {
      throw new BadRequestException('takeOver must be a boolean.');
    }
    const takeOver = takeOverOption === true;
    const result = await this.sessions.heartbeat(
      user.id,
      sessionId,
      body?.clientId,
      takeOver,
    );
    if (takeOver) {
      await this.remoteAuthorization?.invalidateSession(sessionId);
    }
    try {
      await this.remoteAuthorization?.renewActiveGrantsForSession(sessionId);
    } catch (error) {
      this.logger.warn(
        `Unable to renew remote grants for session ${sessionId.slice(0, 8)}: ${error instanceof Error ? error.message : 'Unknown error'}`,
      );
    }
    return result;
  }

  @Post(':sessionId/end')
  @UseGuards(OriginGuard)
  async end(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Body() body: { clientId?: unknown },
  ) {
    const result = await this.sessions.end(user.id, sessionId, body?.clientId);
    await this.remoteAuthorization?.invalidateSession(sessionId);
    if (await this.remoteAuthorization?.isClaimedGuestSession(sessionId, user.id)) {
      await this.remoteAuthorization?.invalidateSession(sessionId, undefined, 'guest');
    }
    return result;
  }

  @Post(':sessionId/remote-pairing')
  @UseGuards(OriginGuard)
  createRemotePairing(
    @CurrentUser() user: User,
    @Param('sessionId') sessionId: string,
    @Body() body: { clientId?: unknown },
  ) {
    return this.remoteAuthorization.createPairingToken(
      user.id,
      sessionId,
      body?.clientId,
    );
  }

  private readCookie(request: Request, name: string): string | undefined {
    for (const item of (request.headers.cookie || '').split(';')) {
      const separator = item.indexOf('=');
      if (separator >= 0 && item.slice(0, separator).trim() === name) {
        return decodeURIComponent(item.slice(separator + 1).trim());
      }
    }
    return undefined;
  }

  private redactSessionId(sessionId: string): string {
    return `${sessionId.slice(0, 8)}…`;
  }
}
